<?php session_start();if(!isset($_SESSION["employee_id"])){header("Location: login.php");exit;}include "db.php";$msg="";
if($_SERVER["REQUEST_METHOD"]==="POST"){$type=$_POST["leave_type"];$from=$_POST["from_date"];$to=$_POST["to_date"];$reason=trim($_POST["reason"]);if($from&&$to&&$reason&&strtotime($to)>=strtotime($from)){$d1=new DateTime($from);$d2=new DateTime($to);$days=$d1->diff($d2)->days+1;$s=$conn->prepare("INSERT INTO leave_applications(employee_id,leave_type,from_date,to_date,days,reason) VALUES(?,?,?,?,?,?)");$s->bind_param("isssis",$_SESSION["employee_id"],$type,$from,$to,$days,$reason);$s->execute();header("Location: my_leaves.php?applied=1");exit;}$msg="Enter valid dates and reason."; }?>
<!doctype html><html><head><title>Apply Leave</title><link rel="stylesheet" href="style.css"></head><body><div class=form><form method=post><h2>Apply for Leave</h2><?php if($msg)echo"<p class=error>".htmlspecialchars($msg)."</p>";?><label>Leave Type</label><select name=leave_type><option>Casual Leave</option><option>Sick Leave</option><option>Earned Leave</option><option>Emergency Leave</option></select><label>From</label><input type=date name=from_date required><label>To</label><input type=date name=to_date required><textarea name=reason placeholder="Reason" required></textarea><button class=btn>Submit</button><p><a href=dashboard.php>Dashboard</a></p></form></div></body></html>